/// @file cpu/scf/minao_data.h
/// @brief MINAO basis data trimmed from ANO. Auto-generated by tools/gen_minao_data.py.
///
/// Matches pyscf.scf.hf.init_guess_by_minao tables bit-for-bit.
/// Do NOT edit by hand -- regenerate via tools/gen_minao_data.py.
#pragma once

namespace ATV {
namespace cpu {
namespace scf {
namespace minao {

/// @brief One contracted shell (single l, possibly multiple contraction columns).
struct Shell {
    int l;          ///< Angular momentum (0=s, 1=p, 2=d, 3=f).
    int n_prim;     ///< Number of primitive Gaussians.
    int n_contract; ///< Number of contracted functions sharing the exponents.
    const double* alpha; ///< [n_prim] exponents.
    const double*
        coeff; ///< [n_prim * n_contract] contraction matrix, row-major (prim, contract).
};

/// @brief MINAO basis for one element.
struct ElementBasis {
    int n_shells;
    int n_ao; ///< Total AOs = sum over shells of (2l+1)*n_contract.
    const Shell* shells;
    const double*
        occupations; ///< [n_ao] fractional occupations (spin-averaged, RHF total).
};

/// @brief Whether element Z is supported (H, C, N, O, F).
inline bool has_minao(int Z) {
    return Z == 1 || Z == 6 || Z == 7 || Z == 8 || Z == 9;
}

/// @brief Retrieve MINAO basis for element Z (throws in callers if unsupported).
const ElementBasis* element_basis(int Z);

} // namespace minao
} // namespace scf
} // namespace cpu
} // namespace ATV
